#!/bin/sh
set -eu
[ "$#" -eq 1 ] && [ -d "$1" ] || { echo "usage: ROLLBACK.sh TARGET_COPY_DIRECTORY" >&2; exit 2; }
rm -f -- "$1/server/src/test/java/com/workforcehub/agent/AgentToolKnowledgeAuthorizationTest.java"
rm -f -- "$1/server/src/test/java/com/workforcehub/agent/workflow/WorkflowContextOperatorTest.java"
rm -f -- "$1/server/src/test/java/com/workforcehub/ragflow/RagflowKnowledgeAccessIntegrationTest.java"
rm -f -- "$1/server/src/test/java/com/workforcehub/ragflow/service/KnowledgeAccessTestFixture.java"
rm -f -- "$1/server/src/test/java/com/workforcehub/ragflow/service/RagflowKnowledgeAccessRepositoryTest.java"
rm -f -- "$1/server/src/test/java/com/workforcehub/ragflow/service/RagflowKnowledgeSearchAuthorizationTest.java"
base64 -d <<'PRISTINE_BYTES' | tar -xz -C "$1"

PRISTINE_BYTES
printf '%s\n' 'ROLLBACK: pristine source restored; added tests removed'
